import re,collections
G=collections.defaultdict(set);n=0
for i in range(1,13):
  for a,b in re.findall(r'C(\d+) depends on C(\d+)',open(f'chunk-{i:02}.txt').read()):
    G[int(a)].add(int(b))
  # SCC
  nodes=set(G)|{x for v in G.values() for x in v}
  def reach(s):
    seen=set();st=[s]
    while st:
      u=st.pop()
      for w in G[u]:
        if w not in seen: seen.add(w);st.append(w)
    return seen
  R={u:reach(u) for u in nodes}
  cyc=sorted(u for u in nodes if u in R[u])
  self=[u for u in nodes if u in G[u]]
  print(i,len(cyc),cyc,'self',self, 'outside', sorted(nodes-set(cyc)))
