best=[]
def dfs(path,vis):
  global best
  u=path[-1]
  for w in G.get(u,()):
    if w==path[0] and len(path)>len(best): best=path[:]
    elif w not in vis and w<N and w>path[0]:
      vis.add(w);path.append(w);dfs(path,vis)
      if len(best)==N: return
      path.pop();vis.discard(w)
dfs([0],{0})
